use proconio::input;
use proconio::marker::Usize1;

fn main() {
    input! { n: Usize1 }
    let mut a = vec![0; n + 3];
    a[n..].fill(1);
    // `n` 回 `next_permutation` します。
    for _ in 0..n {
        let i = a.windows(2).rposition(|w| w[0] < w[1]).unwrap();
        let j = a.iter().rposition(|x| x > &a[i]).unwrap();
        a.swap(i, j);
        a[i + 1..].reverse();
    }
    // 復元します。
    let mut ans = String::new();
    let mut count = 0;
    for x in a {
        count += x;
        if count != 0 && x == 0 {
            ans.push_str(&count.to_string());
        }
    }
    ans.push('3');
    println!("{}", ans);
}

